// Package rich holds event types that use every schema feature event-store
// relies on: sensitive and pii tags, nested, pointer, slice and map fields,
// shared nested types, embedded structs, aliases, time types and defaults.
// Its golden schema was generated by event-store's engine before the
// extraction, so struct-avro must reproduce it byte for byte.
package rich

import "time"

type Address struct {
	Street  string `pii:"data"`
	City    string
	Country string
}

type Profile struct {
	Subject string `sensitive:"subjectID,prefix=usr_"`
	Email   string `sensitive:"data,kind=email"`
	Phones  []string
	Address *Address `pii:"dive"`
	Tags    map[string]string
	Born    time.Time
}

type Base struct {
	At time.Time
	By string
}

type ProfileCreated struct {
	Base
	ID        string
	Profile   Profile   `pii:"dive"`
	Addresses []Address `pii:"dive"`
	TTL       time.Duration
	Score     float64
	Count     int32
	Big       int64
	Active    bool
	Blob      []byte
	Note      *string
}

type ProfileUpdated struct {
	Base
	ID      string
	Profile Profile  `pii:"dive"`
	Prev    *Profile `pii:"dive"`
}

type ProfileDeleted struct {
	_      struct{} `ev:",aliases=ProfileErased"`
	ID     string   `ev:",aliases=ProfileID"`
	Reason string
}

// Samples are the values whose fields become schema defaults.
var (
	SampleCreated = ProfileCreated{Score: 1.5, Active: true, Profile: Profile{Phones: []string{"none"}, Tags: map[string]string{"k": "v"}}}
	SampleUpdated = ProfileUpdated{}
	SampleDeleted = ProfileDeleted{Reason: "user request"}
)
